+#[test]
+fn failed_first_key_update_packet_preserves_valid_update() {
+    let _guard = subscribe();
+    let mut pair = Pair::default();
+    let (client, server) = pair.connect();
+    assert!(!pair.server_conn_mut(server).has_next_crypto());
+    pair.client_conn_mut(client).force_key_update();
+    pair.client_datagrams(client)
+        .send(Bytes::from_static(b"first update"), true)
+        .unwrap();
+    pair.drive_client();
+    let valid = pair.server.inbound.clone();
+    assert!(!valid.is_empty());
+    let mut corrupted = valid.clone();
+    for (_, _, packet) in &mut corrupted {
+        let last = packet.len() - 1;
+        packet[last] ^= 1;
+    }
+    for _ in 0..3 {
+        pair.server.inbound = corrupted.clone();
+        pair.drive_server();
+        assert!(pair.server_conn_mut(server).has_next_crypto());
+        assert!(pair.server_datagrams(server).recv().is_none());
+    }
+    pair.server.inbound = valid;
+    pair.drive();
+    assert_eq!(pair.server_datagrams(server).recv().unwrap(), b"first update"[..]);
+    assert!(!pair.server_conn_mut(server).is_closed());
+}
